import{_ as o,l as n,o as e,c as s,v as l,p as d,x as t,d as i,i as A,S as c}from"./chunks/framework.InCnrqk-.js";const N=JSON.parse('{"title":"Nagle 与延迟 ACK","description":"","frontmatter":{"title":"Nagle 与延迟 ACK","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nagle-delayed-ack.md","filePath":"cs/nagle-delayed-ack.md","lastUpdated":1789023840000}'),C={name:"cs/nagle-delayed-ack.md"};function p(E,a,h,_,g,m){const r=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=l('<h1 id="nagle-与延迟-ack" tabindex="-1">Nagle 与延迟 ACK <a class="header-anchor" href="#nagle-与延迟-ack" aria-label="Permalink to &quot;Nagle 与延迟 ACK&quot;">​</a></h1><div class="epigraph"><p>小段太密会浪费头开销；Nagle 等一个 ACK 再发新的小段。接收方延迟 ACK 想捎带，两套等待叠在一起就会卡住。</p><footer>—— 据 Nagle, RFC 896；RFC 1122 对延迟 ACK；Kurose and Ross</footer></div><p><a href="/cs/tcp-window">上一课</a>用 <code>rwnd</code> 防止淹没对端。本课不重讲滑动窗口。缺口是交互式与 RPC 式负载：一次写几个字节，每个都独立成段，头比载荷大；另一方面接收方为了把 ACK 与反向数据合并而等待。两者各自合理，合在一起造成 <strong>ACK 死锁式延迟</strong>。拥塞窗口下一课才出现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Nagle：若有未确认数据，就把后续小写缓存，直到 ACK 到来或凑满 MSS。延迟 ACK：不立刻确认每个段，等一小段时间或等到两个段。若发送方等 ACK 才发下一小段，接收方等第二段才 ACK，双方都在等。缺口是<strong>把流控窗口里的发送时机写清</strong>，不是新的序号规则。</p><p><span class="marginnote">关闭 Nagle（TCP_NODELAY）是应用在「延迟敏感、载荷小」时的选择，不是协议错误。延迟 ACK 也有上限，避免无限等。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现按 RFC 896 与主机需求（RFC 1122）组合：大块传输几乎不受 Nagle 影响（很快满 MSS）；请求–响应当两端都小段时最疼。修复是打破其中一侧等待：禁 Nagle，或更及时的 ACK。本课不把应用层缓冲策略写成框架教程。</p>',8)),(e(),d(c,null,{default:t(()=>[A(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SMALL%5B%22%E5%B0%8F%E5%86%99%22%5D%20--%3E%20NAGLE%5B%22%E6%9C%89%E6%9C%AA%E7%A1%AE%E8%AE%A4%E5%88%99%E7%BC%93%E5%AD%98%22%5D%0A%20%20DEL%5B%22%E5%BB%B6%E8%BF%9F%20ACK%22%5D%20--%3E%20WAIT%5B%22%E7%AD%89%E7%AC%AC%E4%BA%8C%E6%AE%B5%E6%88%96%E8%B6%85%E6%97%B6%22%5D%0A%20%20NAGLE%20--%3E%20STALL%5B%22%E5%8F%8C%E6%96%B9%E7%AD%89%E5%BE%85%22%5D%0A%20%20WAIT%20--%3E%20STALL%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Nagle 减的是报文率，保护的是共享路径上的头开销；延迟 ACK 减的是纯 ACK 报文。它们优化的是性能，不改变 RFC 793 的可靠性。<a href="/cs/layering-e2e">端到端</a> 字节流语义仍在；变的是何时离开 Nagle 缓冲区。后课拥塞控制会再叠一层「飞行中能有多少 MSS」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入全部 Cork 与自动 Corking 的平台细节。网络队列满时即使 rwnd 很大也不能发，下一课用 <code>cwnd</code>。</p><p>后课默认：小段可能被故意推迟。瓶颈队列的公平与稳定是拥塞控制的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Nagle 合并小段；延迟 ACK 合并确认。</li><li>两套等待叠加会放大 RTT。</li><li>保护网络队列是下一课拥塞控制。</li><li>出处：RFC 896；RFC 1122；Kurose and Ross。</li></ul>',7))])}const T=o(C,[["render",p]]);export{N as __pageData,T as default};
